TypeScript example:

// idiomatic async iterator usage
const stream = await client.stream({ model: 'redwood-compact', input: prompt });
for await (const evt of stream) {
  if (evt.type === 'delta') console.log(evt.delta);
  if (evt.type === 'tool_call') {
    const result = await callExternalTool(evt.tool.name, evt.tool.args);
    await stream.sendToolResult(evt.id, result);
  }
}

// legacy bridge: subscribe(fn) maps to iterator under the hood
const sub = stream.subscribe((evt) => { /* old handler */ });
sub.unsubscribe();

Go example:

// channel-based stream
ch, cancel := client.Stream(ctx, StreamOptions{Model: "redwood-compact", Input: prompt})
defer cancel()
for evt := range ch {
    switch evt.Type {
    case DeltaEvent:
        fmt.Print(evt.Delta)
    case ToolCallEvent:
        res := callTool(evt.Tool.Name, evt.Tool.Args)
        client.SendToolResult(ctx, evt.ID, res)
    }
}

// callback bridge for legacy code
client.StreamWithCallback(ctx, opts, func(evt Event){ /* old-style handler */ })
